	PACKET.CZ.PC_BUY_CASH_POINT_ITEM = function PACKET_CZ_PC_BUY_CASH_POINT_ITEM() {
		this.list = [];
		this.kafrapts = 0;
	};
	PACKET.CZ.PC_BUY_CASH_POINT_ITEM.prototype.build = function() {
		const ver = this.getPacketVersion();
		const itemSize = PacketVerManager_default.value >= 20181121 ? 6 : 4;
		const len = 10 + this.list.length * itemSize;
		const pkt = new BinaryWriter(len);
		pkt.writeShort(ver[1]);
		if (PacketVerManager_default.value < 20100803) {
			pkt.writeShort(this.list[0].ITID);
			pkt.writeShort(this.list[0].count);
			if (PacketVerManager_default.value >= 20070711) pkt.writeShort(this.list[0].price);
			return pkt;
		}
		pkt.writeShort(len);
		pkt.writeULong(this.kafrapts, true);
		pkt.writeShort(this.list.length, true);
		const count = this.list.length;
		for (let i = 0; i < count; ++i) {
			pkt.writeShort(this.list[i].count);
			if (PacketVerManager_default.value >= 20181121) pkt.writeULong(this.list[i].ITID);
			else pkt.writeShort(this.list[i].ITID);
		}
		return pkt;
	};
