	PACKET.CZ.SEARCH_STORE_INFO = function PACKET_CZ_SEARCH_STORE_INFO() {
		this.StoreType = 0;
		this.maxPrice = 0;
		this.minPrice = 0;
		this.ItemIDList = 0;
		this.CardIDList = 0;
	};
	PACKET.CZ.SEARCH_STORE_INFO.prototype.build = function() {
		let i, count, offset;
		const ver = this.getPacketVersion();
		const idSize = PacketVerManager_default.value >= 20181121 ? 4 : 2;
		const pkt_len = 15 + this.ItemIDList.length * idSize + this.CardIDList.length * idSize;
		const pkt = new BinaryWriter(pkt_len);
		pkt.writeShort(ver[1]);
		pkt.view.setInt16(ver[3], pkt_len, true);
		pkt.view.setUint8(ver[4], this.StoreType, true);
		pkt.view.setUint32(ver[5], this.maxPrice, true);
		pkt.view.setUint32(ver[6], this.minPrice, true);
		pkt.view.setUint8(ver[7], this.ItemIDList.length, true);
		pkt.view.setUint8(ver[8], this.CardIDList.length, true);
		offset = ver[9];
		for (i = 0, count = this.ItemIDList.length; i < count; ++i) {
			if (idSize === 4) pkt.view.setUint32(offset, this.ItemIDList[i], true);
			else pkt.view.setUint16(offset, this.ItemIDList[i], true);
			offset += idSize;
		}
		for (i = 0, count = this.CardIDList.length; i < count; ++i) {
			if (idSize === 4) pkt.view.setUint32(offset, this.CardIDList[i], true);
			else pkt.view.setUint16(offset, this.CardIDList[i], true);
			offset += idSize;
		}
		return pkt;
	};
