	PACKET.ZC.SEARCH_STORE_INFO_ACK = function PACKET_ZC_SEARCH_STORE_INFO_ACK(fp, end) {
		const option = new Struct("short index", "short value", "char param");
		const hasExtendedItemId = PacketVerManager_default.value >= 20181121;
		const hasOptions = PacketVerManager_default.value >= 20150226;
		const hasGrade = PacketVerManager_default.value >= 20200916;
		const readSlotCard = () => hasExtendedItemId ? fp.readULong() : fp.readUShort();
		this.IsFirstPage = fp.readUChar();
		this.IsNexPage = fp.readUChar();
		this.RemainedSearchCnt = fp.readUChar();
		this.SSI_List = (function() {
			const out = [];
			while (fp.tell() < end) {
				const entry = {};
				entry.SSI_ID = fp.readULong();
				entry.AID = fp.readULong();
				entry.StoreName = fp.readString(80);
				entry.ITID = hasExtendedItemId ? fp.readULong() : fp.readUShort();
				entry.ItemType = fp.readUChar();
				entry.price = fp.readLong();
				entry.count = fp.readUShort();
				entry.slot = {};
				entry.Options = [];
				if (hasGrade) {
					entry.slot.card1 = readSlotCard();
					entry.slot.card2 = readSlotCard();
					entry.slot.card3 = readSlotCard();
					entry.slot.card4 = readSlotCard();
					if (hasOptions) {
						entry.Options[1] = fp.readStruct(option);
						entry.Options[2] = fp.readStruct(option);
						entry.Options[3] = fp.readStruct(option);
						entry.Options[4] = fp.readStruct(option);
						entry.Options[5] = fp.readStruct(option);
					}
					entry.RefiningLevel = fp.readUChar();
					entry.enchantgrade = fp.readUChar();
					entry.grade = entry.enchantgrade;
				} else {
					entry.RefiningLevel = fp.readUChar();
					entry.slot.card1 = readSlotCard();
					entry.slot.card2 = readSlotCard();
					entry.slot.card3 = readSlotCard();
					entry.slot.card4 = readSlotCard();
					if (hasOptions) {
						entry.Options[1] = fp.readStruct(option);
						entry.Options[2] = fp.readStruct(option);
						entry.Options[3] = fp.readStruct(option);
						entry.Options[4] = fp.readStruct(option);
						entry.Options[5] = fp.readStruct(option);
					}
				}
				entry.card1 = entry.slot.card1;
				entry.card2 = entry.slot.card2;
				entry.card3 = entry.slot.card3;
				entry.card4 = entry.slot.card4;
				out.push(entry);
			}
			return out;
		})();
	};
	PACKET.ZC.SEARCH_STORE_INFO_ACK.size = -1;
