function hasOwn(object, key) {
	return Boolean(object) && Object.prototype.hasOwnProperty.call(object, key);
}
function normalizeQuestDescription(description) {
	if (Array.isArray(description)) return description.map((line) => line == null ? "" : String(line)).join("<br>");
	return description == null ? "" : String(description);
}
function mergeQuestInfo(baseQuest, overrideQuest) {
	const mergedQuest = {
		...baseQuest,
		...overrideQuest || {}
	};
	const description = hasOwn(overrideQuest, "Description") ? overrideQuest.Description : baseQuest.Description;
	const rewardItemList = hasOwn(overrideQuest, "RewardItemList") ? overrideQuest.RewardItemList : baseQuest.RewardItemList;
	return {
		...mergedQuest,
		Description: normalizeQuestDescription(description),
		RewardItemList: (rewardItemList || []).map((item) => ({ ...item }))
	};
}
