//#region src/DB/Map/worldviewdataUtils.js
function mapIdFromResource(resourceName) {
	return resourceName.toLowerCase().replace(/\.(?:rsw|gat)$/i, "");
}
function episodeMetadata(metadataById, mapId) {
	return metadataById.get(mapId) || {
		ep_from: 0,
		ep_to: 99
	};
}
function buildWorldMapSections(mainRows, dungeonRows, resolveMessage, metadataById) {
	const sections = mainRows.map((row) => {
		const [index, resourceName, left, top, right, bottom, messageId, moblevel = ""] = row;
		const id = mapIdFromResource(resourceName);
		const metadata = episodeMetadata(metadataById, id);
		return {
			index,
			id,
			ep_from: metadata.ep_from,
			ep_to: metadata.ep_to,
			name: resolveMessage(messageId),
			top,
			left,
			width: right - left,
			height: bottom - top,
			moblevel,
			type: 0
		};
	});
	for (const row of dungeonRows) {
		const [index, left, top, right, bottom, messageId, moblevel = ""] = row;
		const sourceSection = sections.find((section) => section.index === index && section.type === 0);
		if (!sourceSection) continue;
		sections.push({
			index,
			id: sourceSection.id,
			ep_from: sourceSection.ep_from,
			ep_to: sourceSection.ep_to,
			name: resolveMessage(messageId),
			top,
			left,
			width: right - left,
			height: bottom - top,
			moblevel,
			type: 1
		});
	}
	return sections;
}
