function hydrateSkillDescription(skillIds = SkillConst_default) {
	for (const skillId of Object.keys(SkillDescription)) delete SkillDescription[skillId];
	for (const [skillName, lines] of Object.entries(SkillDescriptionData)) {
		const skillId = skillIds[skillName];
		if (Number.isFinite(skillId) && skillId > 0) SkillDescription[skillId] = `${lines.join("\n")}\n`;
	}
	return SkillDescription;
}
