		/**
		* @type {Object<number, Function[]>} Pending name-resolution callbacks keyed by GID
		* @private
		*/
		static _nameCallbacks = {};
		/**
		* @type {Object<number, ReturnType<typeof setTimeout>>} Per-GID TTL timers
		* @private
		*/
		static _nameCallbackTimers = {};
		/**
		* Request a character name by GID from the server.
		* Returns a Promise that resolves with the name once the server responds.
		* If the name is already cached, resolves immediately.
		* If a request is already in-flight, piggybacks on the pending response.
		*
		* If the server never responds within `ttl` milliseconds the pending
		* callbacks are resolved with 'Unknown', the CNameTable entry is cleared
		* (so the next caller can retry), and all references are freed.
		*
		* @param {number} GID
		* @param {number} [ttl=8000] - Milliseconds before treating the request as timed-out
		* @returns {Promise<string>} resolves with the character name
		*/
		static getNameByGID(GID, ttl = 8e3) {
			if (DB.CNameTable[GID] && DB.CNameTable[GID] !== "Unknown") return Promise.resolve(DB.CNameTable[GID]);
			if (DB.CNameTable[GID] === "Unknown") return new Promise((resolve) => {
				if (!DB._nameCallbacks[GID]) DB._nameCallbacks[GID] = [];
				DB._nameCallbacks[GID].push(resolve);
			});
			let pkt;
			if (PacketVerManager_default.value >= 20180307) pkt = new PACKET.CZ.REQNAME_BYGID2();
			else pkt = new PACKET.CZ.REQNAME_BYGID();
			pkt.GID = GID;
			Network.sendPacket(pkt);
			DB.CNameTable[pkt.GID] = "Unknown";
			DB._nameCallbackTimers[GID] = setTimeout(() => {
				if (DB._nameCallbacks[GID]) {
					delete DB.CNameTable[GID];
					DB._resolveNameCallbacks(GID, "Unknown");
				}
				delete DB._nameCallbackTimers[GID];
			}, ttl);
			return new Promise((resolve) => {
				if (!DB._nameCallbacks[GID]) DB._nameCallbacks[GID] = [];
				DB._nameCallbacks[GID].push(resolve);
			});
		}
		/**
		* Notify all pending name-resolution callbacks for a GID.
		* Called internally when a name response packet arrives.
		*
		* @param {number} GID
		* @param {string} name
		* @private
		*/
		static _resolveNameCallbacks(GID, name) {
			if (DB._nameCallbackTimers[GID]) {
				clearTimeout(DB._nameCallbackTimers[GID]);
				delete DB._nameCallbackTimers[GID];
			}
			const callbacks = DB._nameCallbacks[GID];
			if (callbacks) {
				delete DB._nameCallbacks[GID];
				for (const cb of callbacks) cb(name);
			}
		}
		/**
		* Get Pet talk message
		*
		* @param {integer} message data combined with mob id, hungryState, actionState
		* @return {string} pet telk sentence
		*
		* @author MrUnzO
		*/
		static getPetTalk(data) {
			const mobId = parseInt(data.toString().substring(0, 4)) || 1001;
			const hungryState = parseInt(data.toString().substring(4, 6)) || 0;
			const actionState = parseInt(data.toString().substring(6, 7)) || 0;
			if (hungryState >= Object.keys(PetHungryState_default).length || actionState >= Object.keys(PetMessageConst_default).length) return false;
			let mobName, hungryText, actionText;
			if (mobId && mobId >= 1e3 && mobId < 4e3) mobName = (MonsterTable_default[mobId] || MonsterTable_default[1001]).toLowerCase();
			if (hungryState !== null && hungryState !== void 0) hungryText = DB.getPetHungryText(parseInt(hungryState));
			if (actionState !== null && actionState !== void 0) actionText = DB.getPetActText(parseInt(actionState));
			if (!mobName || !hungryText || !actionText) return false;
			if (PetTalkTable && PetTalkTable[mobName] && PetTalkTable[mobName][hungryText] && PetTalkTable[mobName][hungryText][actionText]) {
				let rnd = 0;
				if (PetTalkTable[mobName][hungryText][actionText] instanceof Array) {
					rnd = parseInt(Math.random() * 100 % PetTalkTable[mobName][hungryText][actionText].length);
					return CodepageManager.decodeString(PetTalkTable[mobName][hungryText][actionText][rnd]);
				}
				return CodepageManager.decodeString(PetTalkTable[mobName][hungryText][actionText]);
			}
			return false;
		}
		/**
		* Get Pet Hungry state
		*
		* @param {integer} hunger
		* @return {integer} hunger state
		*
		* @author MrUnzO
		*/
		static getPetHungryState(hunger) {
			if (!hunger) return 0;
			if (hunger > 90 && hunger <= 100) return PetHungryState_default.PET_FULL;
			else if (hunger > 75 && hunger <= 90) return PetHungryState_default.PET_ENOUGH;
			else if (hunger > 25 && hunger <= 75) return PetHungryState_default.PET_SATISFIED;
			else if (hunger > 10 && hunger <= 25) return PetHungryState_default.PET_HUNGRY;
			else if (hunger >= 0 && hunger <= 10) return PetHungryState_default.PET_HUNGER;
			return 0;
		}
		/**
		* Get Pet Friendly state
		*
		* @param {integer} friendly
		* @return {integer} friendly state
		*
		* @author MrUnzO
		*/
		static getPetFriendlyState(friendly) {
			if (!friendly) return 0;
			if (friendly > 900 && friendly <= 1e3) return PetFriendlyState_default.PET_FAMILIAR;
			else if (friendly > 750 && friendly <= 900) return PetFriendlyState_default.PET_FRIENDLY;
			else if (friendly > 250 && friendly <= 750) return PetFriendlyState_default.PET_NORMAL;
			else if (friendly > 100 && friendly <= 250) return PetFriendlyState_default.PET_AWKWARD;
			else if (friendly >= 0 && friendly <= 100) return PetFriendlyState_default.PET_ASHAMED;
			return 0;
		}
