function triggerMobileControlFeedback(control) {
	if (!control) return;
	const previousTimer = mobileControlFeedbackTimers.get(control);
	if (previousTimer) clearTimeout(previousTimer);
	control.classList.remove("tap-feedback");
	control.offsetWidth;
	control.classList.add("tap-feedback");
	mobileControlFeedbackTimers.set(control, setTimeout(function() {
		control.classList.remove("tap-feedback");
		mobileControlFeedbackTimers.delete(control);
	}, 280));
}
function positionRightBar() {
	const rightBar = MobileUI.ui.find("#rightBar")[0];
	if (!rightBar) return;
	const viewportHeight = Renderer.height || window.innerHeight;
	const viewportPadding = 8;
	const fallbackMenuTop = viewportHeight - 48;
	const gameMenuHost = document.getElementById("GameMenu");
	const menuToggle = gameMenuHost && gameMenuHost.shadowRoot ? gameMenuHost.shadowRoot.querySelector(".menu-toggle") : null;
	const menuTop = menuToggle ? menuToggle.getBoundingClientRect().top : fallbackMenuTop;
	const preferredTop = viewportHeight * .65 - rightBar.offsetHeight / 2;
	const maximumTop = Math.max(viewportPadding, menuTop - viewportPadding - rightBar.offsetHeight);
	rightBar.style.top = `${Math.round(Math.max(viewportPadding, Math.min(preferredTop, maximumTop)))}px`;
}
function scheduleRightBarLayout() {
	if (rightBarLayoutFrame) cancelAnimationFrame(rightBarLayoutFrame);
	rightBarLayoutFrame = requestAnimationFrame(() => {
		rightBarLayoutFrame = null;
		positionRightBar();
	});
}
/**
* Logs the key press to the console and performs the key press action.
* @param {number} keyCode - The key code of the pressed key.
*/
function logKeyPress(keyCode) {
	keyPress(keyCode);
}
/**
* Toggles full screen display
*/
function toggleFullScreen() {
	if (!Context.isFullScreen()) Context.requestFullScreen();
	else Context.cancelFullScreen();
}
/**
* Emulates a keypress event
*
* @param {number} keyId
*/
function keyPress(k) {
	const roWindow = window;
	roWindow.document.getElementsByTagName("body")[0].focus();
	roWindow.dispatchEvent(new KeyboardEvent("keydown", {
		keyCode: k,
		which: k
	}));
}
