function onBarterChanceList(pkt) {
	pendingBarterOptions = new Map(pkt.itemList.map((item) => [item.index, item]));
}
/**
* Received items list to from expanded barter NPC
*
* @param {object} pkt - PACKET.ZC.NPC_EXPANDED_BARTER_MARKET_ITEMINFO
*/
function onExpandedBarterBuyList(pkt) {
	const barterItems = pkt.itemList.map((item) => {
		const options = pendingBarterOptions.get(item.index);
		return {
			...item,
			successChance: options?.successChance ?? 100,
			blacksmithBlessingAmount: options?.blacksmithBlessingAmount ?? 0,
			preservedRequirementsMask: options?.preservedRequirementsMask ?? 0
		};
	});
	pendingBarterOptions.clear();
	NpcStore_default.append();
	NpcStore_default.setType(NpcStore_default.Type.BARTER_MARKET_EXTENDED);
	NpcStore_default.setList(barterItems);
	NpcStore_default.onSubmit = (itemList) => {
		const _pkt = new PACKET.CZ.NPC_EXPANDED_BARTER_MARKET_PURCHASE();
		const count = itemList.length;
		for (let i = 0; i < count; ++i) _pkt.itemList.push({
			itemId: itemList[i].ITID,
			shopIndex: itemList[i].index + (itemList[i].useBlacksmithBlessing ? 2147483648 : 0),
			amount: itemList[i].count
		});
		Network.sendPacket(_pkt);
	};
}
