function onSourceAwareSellList(pkt) {
	if (pkt.invalid) {
		ChatBox_default.addText("The NPC sell list could not be read.", ChatBox_default.TYPE.ERROR, ChatBox_default.FILTER.PUBLIC_LOG);
		Network.sendPacket(PacketVerManager_default.value >= 20131223 ? new PACKET.CZ.NPC_TRADE_QUIT() : new PACKET.CZ.PC_SELL_ITEMLIST());
		return;
	}
	NpcStore_default.append();
	NpcStore_default.setType(NpcStore_default.Type.SELL);
	NpcStore_default.setList(pkt.itemList);
	NpcStore_default.onSubmit = (itemList) => {
		const submitPacket = new PACKET.CZ.NPC_SOURCE_AWARE_SELL_ITEMLIST();
		submitPacket.schemaVersion = pkt.schemaVersion;
		submitPacket.shopGid = pkt.shopGid;
		for (const item of itemList) submitPacket.itemList.push({
			source: item.source,
			index: item.index,
			amount: item.count
		});
		Network.sendPacket(submitPacket);
	};
}
